:root {
    --bg: #0a1628;
    --panel: #142943;
    --panel-2: #0d1d30;
    --panel-3: #10233a;
    --border: #1e3a5f;
    --border-soft: rgba(30, 58, 95, 0.62);
    --text: #ffffff;
    --muted: #8b9cb3;
    --primary: #00d9ff;
    --primary-dark: #0099cc;
    --gold: #ffb800;
    --success: #00e676;
    --warning: #ffa726;
    --danger: #ff5252;
    --pitcher: #e63946;
    --shadow: 0 18px 60px rgba(0, 0, 0, 0.28);
    --radius: 18px;
}

* {
    box-sizing: border-box;
}

html {
    background: var(--bg);
}

body {
    margin: 0;
    min-height: 100vh;
    color: var(--text);
    font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    background:
        radial-gradient(circle at 10% 0%, rgba(0, 217, 255, 0.12), transparent 30%),
        radial-gradient(circle at 90% 10%, rgba(255, 184, 0, 0.08), transparent 32%),
        var(--bg);
}

body::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    background-image: linear-gradient(rgba(255,255,255,0.025) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.025) 1px, transparent 1px);
    background-size: 44px 44px;
    mask-image: linear-gradient(to bottom, black, transparent 80%);
}

a {
    color: inherit;
}

button,
.button-link,
.secondary-button {
    border: 0;
    border-radius: 12px;
    padding: 11px 16px;
    font-weight: 800;
    letter-spacing: -0.01em;
    text-decoration: none;
    cursor: pointer;
    color: #06101f;
    background: linear-gradient(135deg, var(--primary), #54ecff);
    box-shadow: 0 12px 30px rgba(0, 217, 255, 0.18);
    transition: transform 0.18s ease, box-shadow 0.18s ease, opacity 0.18s ease;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    white-space: nowrap;
}

button:hover,
.button-link:hover,
.secondary-button:hover {
    transform: translateY(-1px);
    box-shadow: 0 18px 34px rgba(0, 217, 255, 0.26);
}

button:disabled {
    cursor: not-allowed;
    opacity: 0.45;
    transform: none;
    box-shadow: none;
    color: var(--muted);
    background: #1e3a5f;
}

.button-link.secondary,
.secondary-button {
    background: #1e3a5f;
    color: var(--text);
    box-shadow: none;
}

.icon-button {
    width: 36px;
    height: 36px;
    padding: 0;
    border-radius: 12px;
    font-size: 22px;
    line-height: 1;
}

.icon-button.danger {
    color: #fff;
    background: rgba(255, 82, 82, 0.18);
    border: 1px solid rgba(255, 82, 82, 0.35);
    box-shadow: none;
}

input,
select,
textarea {
    width: 100%;
    border: 1px solid var(--border);
    background: #0a1628;
    color: var(--text);
    border-radius: 12px;
    padding: 11px 12px;
    outline: none;
    transition: border-color 0.16s ease, box-shadow 0.16s ease;
}

input:focus,
select:focus,
textarea:focus {
    border-color: var(--primary);
    box-shadow: 0 0 0 3px rgba(0, 217, 255, 0.12);
}

label {
    display: block;
    color: var(--muted);
    font-size: 13px;
    font-weight: 800;
    margin-bottom: 8px;
}

.site-header {
    position: sticky;
    top: 0;
    z-index: 50;
    border-bottom: 1px solid rgba(30, 58, 95, 0.78);
    background: rgba(10, 22, 40, 0.88);
    backdrop-filter: blur(18px);
}

.header-inner,
.page-wrap {
    width: min(1480px, calc(100% - 36px));
    margin: 0 auto;
}

.header-inner {
    min-height: 72px;
    display: grid;
    grid-template-columns: auto 1fr auto;
    align-items: center;
    gap: 22px;
}

.header-brand-group {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    min-width: max-content;
}

.player-detail-back-link {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    min-height: 38px;
    padding: 9px 12px;
    border-radius: 14px;
    color: var(--muted);
    text-decoration: none;
    font-size: 13px;
    font-weight: 900;
    letter-spacing: -0.01em;
    background: rgba(255, 255, 255, 0.035);
    border: 1px solid rgba(255, 255, 255, 0.09);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.045);
    transition:
        color 0.16s ease,
        border-color 0.16s ease,
        background 0.16s ease,
        transform 0.16s ease,
        box-shadow 0.16s ease;
}

.player-detail-back-link:hover,
.player-detail-back-link:focus-visible {
    color: var(--text);
    background: rgba(8, 212, 223, 0.08);
    border-color: rgba(8, 212, 223, 0.24);
    box-shadow: 0 0 0 3px rgba(8, 212, 223, 0.08);
    transform: translateX(-2px);
    outline: none;
}

.player-detail-back-arrow {
    color: var(--primary);
    font-size: 16px;
    line-height: 1;
}

.brand {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    text-decoration: none;
    font-size: 20px;
    font-weight: 900;
}

.brand-mark {
    width: 40px;
    height: 40px;
    border-radius: 14px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, var(--primary), var(--primary-dark));
    box-shadow: 0 12px 30px rgba(0, 217, 255, 0.22);
}

.brand-text strong {
    color: var(--primary);
}

.main-nav,
.auth-nav,
.tab-nav,
.hero-actions,
.card-actions,
.chip-row,
.form-actions {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
}

.main-nav {
    justify-content: center;
}

.main-nav a,
.auth-nav a,
.tab-nav a {
    color: var(--muted);
    text-decoration: none;
    border-radius: 12px;
    padding: 10px 14px;
    font-weight: 800;
    font-size: 14px;
    transition: background 0.16s ease, color 0.16s ease;
}

.main-nav a:hover,
.auth-nav a:hover,
.tab-nav a:hover {
    color: var(--text);
    background: rgba(30, 58, 95, 0.72);
}

.main-nav a.active,
.tab-nav a.active {
    color: var(--primary);
    background: rgba(0, 217, 255, 0.1);
}

.auth-nav {
    justify-content: flex-end;
}

.auth-nav .nav-cta {
    color: #06101f;
    background: var(--primary);
}

.user-name {
    color: var(--muted);
    font-size: 14px;
    font-weight: 800;
}

.page-wrap {
    padding: 28px 0 60px;
}

.flash-wrap {
    padding-bottom: 0;
}

.flash-box,
.notice-panel,
.notice-box,
.error-box,
.success-box {
    border-radius: 16px;
    padding: 14px 16px;
    margin-bottom: 18px;
    border: 1px solid rgba(255, 184, 0, 0.35);
    background: rgba(255, 184, 0, 0.11);
    color: #ffe9a6;
}

.flash-box p,
.notice-panel p {
    margin: 4px 0;
}

.notice-panel.error,
.error-box {
    color: #ffd2d2;
    border-color: rgba(255, 82, 82, 0.42);
    background: rgba(255, 82, 82, 0.1);
}

.notice-panel.success,
.success-box,
.notice-box {
    color: #baffd8;
    border-color: rgba(0, 230, 118, 0.36);
    background: rgba(0, 230, 118, 0.1);
}

.notice-panel.warning {
    color: #ffe3ad;
    border-color: rgba(255, 167, 38, 0.42);
    background: rgba(255, 167, 38, 0.1);
}

.hero-panel,
.content-card {
    border: 1px solid var(--border-soft);
    background: linear-gradient(180deg, rgba(20, 41, 67, 0.96), rgba(13, 29, 48, 0.96));
    border-radius: 24px;
    box-shadow: var(--shadow);
}

.hero-panel {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 24px;
    padding: 34px;
    margin-bottom: 24px;
    overflow: hidden;
    position: relative;
}

.hero-panel::after {
    content: "";
    position: absolute;
    width: 300px;
    height: 300px;
    right: -120px;
    top: -140px;
    border-radius: 999px;
    background: radial-gradient(circle, rgba(0, 217, 255, 0.18), transparent 68%);
}

.eyebrow {
    color: var(--primary);
    text-transform: uppercase;
    letter-spacing: 0.12em;
    font-size: 12px;
    font-weight: 900;
    margin: 0 0 8px;
}

h1,
h2,
h3,
h4,
p {
    margin-top: 0;
}

h1 {
    font-size: clamp(34px, 4vw, 56px);
    line-height: 1.02;
    letter-spacing: -0.045em;
    margin-bottom: 12px;
}

h2 {
    font-size: 25px;
    letter-spacing: -0.03em;
    margin-bottom: 0;
}

h3 {
    font-size: 18px;
    letter-spacing: -0.02em;
}

.hero-copy,
.small-text,
.muted-text,
.empty-table-text,
.auth-footnote {
    color: var(--muted);
}

.hero-copy {
    max-width: 740px;
    line-height: 1.7;
    margin-bottom: 0;
}

.hero-metric {
    position: relative;
    z-index: 1;
    min-width: 170px;
    border-radius: 22px;
    background: #0a1628;
    border: 1px solid var(--border);
    padding: 20px;
    text-align: center;
}

.hero-metric span,
.stat-card span,
.score-summary-item span,
.stat-tile span,
.mini-stat-grid span {
    display: block;
    color: var(--muted);
    font-size: 13px;
    font-weight: 800;
    margin-bottom: 6px;
}

.hero-metric strong,
.stat-card strong,
.score-summary-item strong {
    display: block;
    font-size: 32px;
    color: var(--text);
}

.content-card {
    padding: 24px;
    margin-bottom: 24px;
}

.compact-card {
    padding: 16px;
}

.section-heading {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 16px;
    margin-bottom: 20px;
}

.section-heading.split {
    align-items: center;
}

.summary-strip {
    display: flex;
    gap: 18px;
    color: var(--muted);
    margin-top: 14px;
    flex-wrap: wrap;
}

.summary-strip strong {
    color: var(--text);
}

.table-wrap {
    overflow-x: auto;
    border: 1px solid var(--border);
    border-radius: 18px;
}

.compact-table-wrap {
    border-radius: 14px;
}

.data-table {
    width: 100%;
    border-collapse: collapse;
    min-width: 860px;
}

.data-table th,
.data-table td {
    padding: 16px;
    border-bottom: 1px solid rgba(30, 58, 95, 0.68);
    text-align: center;
    vertical-align: middle;
}

.data-table th {
    color: var(--muted);
    background: #0d1d30;
    font-size: 13px;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.data-table tr:last-child td {
    border-bottom: 0;
}

.data-table tr:hover td {
    background: rgba(30, 58, 95, 0.22);
}

.player-cell {
    display: flex;
    align-items: center;
    gap: 12px;
    text-align: left;
}

.player-link,
.player-name-large {
    color: var(--text);
    font-weight: 900;
    text-decoration: none;
}

.player-link:hover,
.player-name-large:hover {
    color: var(--primary);
}

.player-name-large {
    font-size: 20px;
}

.points,
.price-up,
.budget-ok,
.count-ok {
    color: var(--success);
    font-weight: 900;
}

.price-down,
.budget-danger,
.count-danger {
    color: var(--danger);
    font-weight: 900;
}

.price-same {
    color: var(--muted);
    font-weight: 900;
}

.team-badge,
.type-chip,
.position-badge,
.status-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
    border-radius: 999px;
    font-size: 12px;
    font-weight: 900;
    line-height: 1;
    white-space: nowrap;
}


.team-default { --team-primary: #1e3a5f; --team-secondary: #8b9cb3; }
.team-kia { --team-primary: #ea0029; --team-secondary: #06141f; }
.team-lg { --team-primary: #c30452; --team-secondary: #000000; }
.team-doosan { --team-primary: #131230; --team-secondary: #ed1c24; }
.team-samsung { --team-primary: #074ca1; --team-secondary: #c5c5c5; }
.team-kt { --team-primary: #000000; --team-secondary: #eb1c24; }
.team-ssg { --team-primary: #ce0e2d; --team-secondary: #ffd700; }
.team-lotte { --team-primary: #041e42; --team-secondary: #d00f31; }
.team-nc { --team-primary: #315288; --team-secondary: #c59f6e; }
.team-kiwoom { --team-primary: #820024; --team-secondary: #6e0019; }
.team-hanwha { --team-primary: #ff6600; --team-secondary: #000000; }

.team-badge {
    color: white;
    background: var(--team-primary);
    border: 1px solid rgba(255,255,255,0.16);
    box-shadow: inset 0 -12px 24px rgba(0,0,0,0.12);
}

.team-badge-xs { padding: 5px 7px; font-size: 10px; }
.team-badge-sm { padding: 7px 9px; }
.team-badge-md { padding: 9px 12px; font-size: 13px; }

.type-chip,
.position-badge {
    padding: 7px 9px;
    background: rgba(0, 217, 255, 0.1);
    color: var(--primary);
    border: 1px solid rgba(0, 217, 255, 0.22);
}

.type-chip.pitcher,
.position-badge.pitcher {
    background: rgba(230, 57, 70, 0.12);
    color: #ff7883;
    border-color: rgba(230, 57, 70, 0.28);
}

.status-badge {
    padding: 9px 12px;
    border-radius: 12px;
}

.status-badge.confirmed { color: var(--success); background: rgba(0, 230, 118, 0.12); }
.status-badge.ready { color: var(--primary); background: rgba(0, 217, 255, 0.12); }
.status-badge.warning { color: var(--warning); background: rgba(255, 167, 38, 0.12); }
.status-badge.pending { color: var(--muted); background: rgba(139, 156, 179, 0.12); }

.rank-medal,
.rank-number {
    width: 34px;
    height: 34px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 999px;
    font-weight: 950;
    color: #06101f;
}

.rank-number {
    color: var(--text);
    background: #1e3a5f;
}

.rank-medal.gold { background: linear-gradient(135deg, #ffd700, #ffb800); }
.rank-medal.silver { background: linear-gradient(135deg, #f3f3f3, #c0c0c0); }
.rank-medal.bronze { background: linear-gradient(135deg, #e0a05a, #cd7f32); }
.rank-row.rank-1 td { background: linear-gradient(90deg, rgba(255, 215, 0, 0.12), transparent); }
.rank-row.rank-2 td { background: linear-gradient(90deg, rgba(192, 192, 192, 0.1), transparent); }
.rank-row.rank-3 td { background: linear-gradient(90deg, rgba(205, 127, 50, 0.1), transparent); }
.my-team-row td,
.podium-card.my-team-row { outline: 2px solid rgba(0, 217, 255, 0.35); outline-offset: -2px; }

.uniform {
    position: relative;
    display: inline-flex;
    flex-shrink: 0;
    filter: drop-shadow(0 10px 16px rgba(0,0,0,0.24));
}

.uniform svg {
    width: 100%;
    height: 100%;
}

.uniform-sm { width: 38px; height: 50px; }
.uniform-md { width: 58px; height: 76px; }
.uniform-lg { width: 110px; height: 146px; }

.uniform-body,
.uniform-sleeve {
    fill: var(--team-primary);
    stroke: var(--team-secondary);
    stroke-width: 1.2;
}

.uniform-collar {
    fill: var(--team-secondary);
}

.uniform-line {
    stroke: var(--team-secondary);
    stroke-width: 2;
    opacity: 0.55;
}

.uniform-number {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #fff;
    text-shadow: 0 2px 4px rgba(0,0,0,0.65);
    font-weight: 950;
    letter-spacing: -0.04em;
}

.uniform-sm .uniform-number { font-size: 11px; }
.uniform-md .uniform-number { font-size: 15px; }
.uniform-lg .uniform-number { font-size: 28px; }

.filter-grid {
    display: grid;
    grid-template-columns: 2fr repeat(5, minmax(130px, 1fr));
    gap: 14px;
    align-items: end;
}

.form-field.wide {
    min-width: 220px;
}

.form-actions.full {
    width: 100%;
}

.form-row-2 {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
}

.player-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 18px;
}

.full-width-card {
    grid-column: 1 / -1;
}

.player-card-v2 {
    border: 1px solid var(--border-soft);
    background: linear-gradient(180deg, #142943, #0d1d30);
    border-radius: 22px;
    padding: 18px;
    min-height: 225px;
}

.card-glow {
    transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
}
.card-glow:hover {
    transform: translateY(-3px);
    border-color: rgba(0, 217, 255, 0.48);
    box-shadow: 0 18px 46px rgba(0, 217, 255, 0.12);
}

.player-card-top {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 16px;
}

.player-card-main {
    min-width: 0;
}

.chip-row.compact {
    gap: 6px;
}

.mini-stat-grid,
.metric-grid,
.score-summary-grid,
.stat-tile-grid,
.budget-row {
    display: grid;
    gap: 14px;
}

.mini-stat-grid {
    grid-template-columns: repeat(2, 1fr);
}

.mini-stat-grid > div,
.score-summary-item,
.stat-tile {
    background: #0a1628;
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 14px;
}

.mini-stat-grid strong,
.stat-tile strong {
    font-size: 20px;
}

.clamp-text {
    display: -webkit-box;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
    margin: 14px 0 0;
}

.editor-layout {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 420px;
    gap: 24px;
    align-items: start;
}

.editor-main {
    min-width: 0;
}

.sticky-card {
    position: sticky;
    top: 96px;
}

.team-status-card .budget-row {
    grid-template-columns: repeat(3, 1fr);
    margin-bottom: 16px;
}

.budget-row > div {
    background: #0a1628;
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 14px;
}

.budget-row strong {
    display: block;
    font-size: 24px;
}

.progress-track {
    height: 12px;
    overflow: hidden;
    border-radius: 999px;
    background: #0a1628;
    border: 1px solid var(--border);
    margin-bottom: 16px;
}

.progress-fill {
    height: 100%;
    border-radius: 999px;
    background: linear-gradient(90deg, var(--primary), var(--success));
}

.progress-fill.danger {
    background: var(--danger);
}

.baseball-field {
    position: relative;
    width: min(100%, 760px);
    aspect-ratio: 1 / 1;
    margin: 0 auto;
    border-radius: 30px;
    overflow: hidden;
}

.field-bg {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
}

.field-bg rect { fill: #0a1628; }
.field-bg .outfield-arc,
.field-bg .diamond-line { fill: none; stroke: #1e3a5f; stroke-width: 2; stroke-dasharray: 7 5; }
.field-bg .diamond-line { stroke-dasharray: none; }
.field-bg .base-line { stroke: #2a4a70; stroke-width: 1; }
.field-bg .mound { fill: #1e3a5f; stroke: var(--primary); stroke-width: 2; }
.field-bg .home-plate { fill: #1e3a5f; stroke: #8b9cb3; stroke-width: 1; }

.field-position {
    position: absolute;
    width: 174px;
    transform: translate(-50%, -50%);
}

.pos-lf { left: 23%; top: 28%; }
.pos-cf { left: 50%; top: 16%; }
.pos-rf { left: 77%; top: 28%; }
.pos-ss { left: 35%; top: 45%; }
.pos-2b { left: 65%; top: 45%; }
.pos-3b { left: 24%; top: 62%; }
.pos-1b { left: 76%; top: 62%; }
.pos-p1 { left: 50%; top: 59%; }
.pos-c { left: 43%; top: 82%; }
.pos-util { left: 58%; top: 82%; }

.bullpen-strip {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 12px;
    margin-top: 16px;
}

.field-slot {
    position: relative;
    min-height: 126px;
    border: 1px solid rgba(30, 58, 95, 0.84);
    border-radius: 18px;
    padding: 12px;
    background: rgba(13, 29, 48, 0.88);
    backdrop-filter: blur(8px);
}

.field-slot.filled {
    border-color: rgba(0, 217, 255, 0.28);
}

.slot-topline,
.slot-player-main,
.slot-stats {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

.slot-code {
    color: var(--primary);
    font-weight: 950;
}

.slot-label {
    color: var(--muted);
    font-size: 12px;
    font-weight: 800;
}

.slot-player-main {
    justify-content: flex-start;
    margin-top: 8px;
}

.slot-player-text {
    min-width: 0;
}

.slot-meta {
    display: flex;
    gap: 5px;
    flex-wrap: wrap;
    margin-top: 5px;
}

.slot-stats {
    margin-top: 10px;
    color: var(--muted);
    font-size: 12px;
    font-weight: 800;
}

.slot-stats strong,
.slot-stats span:first-child {
    color: var(--text);
}

.slot-stats small {
    color: var(--muted);
}

.slot-remove-form {
    position: absolute;
    top: 8px;
    right: 8px;
}

.empty-slot-content {
    height: 82px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    color: var(--muted);
    gap: 6px;
    font-weight: 800;
}

.empty-plus {
    width: 32px;
    height: 32px;
    border-radius: 999px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1px dashed var(--border);
    color: var(--primary);
    font-size: 22px;
}

.side-filter {
    display: grid;
    gap: 12px;
    margin-bottom: 16px;
}

.search-result-list {
    display: grid;
    gap: 10px;
    max-height: 780px;
    overflow: auto;
    padding-right: 4px;
}

.market-player-card {
    display: grid;
    grid-template-columns: auto 1fr auto;
    gap: 10px;
    align-items: center;
    border: 1px solid var(--border);
    background: #0a1628;
    border-radius: 16px;
    padding: 10px;
}

.market-player-info {
    min-width: 0;
}

.dashboard-grid {
    display: grid;
    grid-template-columns: 2fr repeat(3, 1fr);
    gap: 18px;
    margin-bottom: 24px;
}

.team-identity-card {
    margin-bottom: 0;
}

.stat-card {
    margin-bottom: 0;
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.stat-card small {
    color: var(--muted);
    font-weight: 800;
    margin-top: 4px;
}

.score-summary-grid {
    grid-template-columns: repeat(4, 1fr);
    margin-bottom: 24px;
}

.chart-and-table,
.detail-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.2fr) minmax(360px, 0.8fr);
    gap: 24px;
}

.chart-card {
    min-width: 0;
}

.empty-state {
    text-align: center;
    color: var(--muted);
    padding: 34px;
}

.empty-state strong {
    color: var(--text);
    font-size: 20px;
}

.player-hero-detail {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 24px;
    align-items: center;
}

.player-hero-info h1 {
    margin: 8px 0 14px;
}

.player-meta-line {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    color: var(--muted);
    font-weight: 800;
}

.player-meta-line span {
    padding: 8px 10px;
    border-radius: 10px;
    background: #0a1628;
    border: 1px solid var(--border);
}

.metric-grid.four {
    grid-template-columns: repeat(4, 1fr);
    margin-bottom: 24px;
}

.stat-tile-grid {
    grid-template-columns: repeat(2, 1fr);
}

.stat-tile strong {
    display: block;
    color: var(--text);
}

.detail-cell {
    text-align: left;
    min-width: 260px;
}

.detail-pill {
    display: inline-flex;
    margin: 3px;
    padding: 6px 8px;
    border-radius: 999px;
    background: rgba(30, 58, 95, 0.65);
    color: var(--muted);
    font-size: 12px;
    font-weight: 800;
}

.price-history-list {
    display: grid;
    gap: 12px;
}

.price-history-item {
    display: flex;
    justify-content: space-between;
    gap: 16px;
    border: 1px solid var(--border);
    background: #0a1628;
    border-radius: 16px;
    padding: 14px;
}

.price-history-item p {
    color: var(--muted);
    margin: 5px 0 0;
    line-height: 1.45;
}

.price-history-price {
    text-align: right;
    white-space: nowrap;
}

.price-history-price span {
    display: block;
    color: var(--muted);
    margin-bottom: 5px;
}

.podium-wrap {
    display: flex;
    align-items: flex-end;
    justify-content: center;
    gap: 18px;
    margin: 34px 0;
}

.podium-card {
    position: relative;
    width: min(260px, 32%);
    border-radius: 24px;
    padding: 34px 22px 22px;
    text-align: center;
    background: linear-gradient(180deg, #142943, #0d1d30);
    border: 1px solid var(--border);
    box-shadow: var(--shadow);
}

.podium-card.first {
    transform: translateY(-22px);
    min-height: 210px;
}

.podium-medal {
    position: absolute;
    top: -18px;
    left: 50%;
    transform: translateX(-50%);
    width: 58px;
    height: 58px;
    border-radius: 999px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #06101f;
    font-weight: 950;
}

.podium-card.gold .podium-medal { background: linear-gradient(135deg, #ffd700, #ffb800); }
.podium-card.silver .podium-medal { background: linear-gradient(135deg, #f3f3f3, #c0c0c0); }
.podium-card.bronze .podium-medal { background: linear-gradient(135deg, #e0a05a, #cd7f32); }
.podium-card h3 { margin: 12px 0 6px; }
.podium-card p { color: var(--muted); }
.podium-card strong { color: var(--primary); font-size: 30px; }

.auth-shell {
    min-height: calc(100vh - 200px);
    display: grid;
    place-items: center;
}

.auth-card {
    width: min(520px, 100%);
}

.auth-form {
    display: grid;
    gap: 16px;
}

.auth-footnote {
    margin: 18px 0 0;
    text-align: center;
}

.auth-footnote a {
    color: var(--primary);
    font-weight: 900;
}

.empty-slot-row td,
.empty-slot-text {
    color: var(--muted);
}

.position-nowrap {
    white-space: nowrap;
}

.warning-icon {
    color: var(--warning);
}

.complete-badge {
    display: inline-flex;
    border-radius: 999px;
    padding: 7px 9px;
    color: var(--success);
    background: rgba(0, 230, 118, 0.12);
    font-size: 12px;
    font-weight: 900;
}

.team-title {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}

::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}
::-webkit-scrollbar-track { background: #0a1628; }
::-webkit-scrollbar-thumb { background: #1e3a5f; border-radius: 99px; }
::-webkit-scrollbar-thumb:hover { background: #2a4a70; }

@media (max-width: 1180px) {
    .editor-layout,
    .chart-and-table,
    .detail-grid {
        grid-template-columns: 1fr;
    }
    .sticky-card {
        position: static;
    }
    .dashboard-grid,
    .metric-grid.four {
        grid-template-columns: repeat(2, 1fr);
    }
    .team-identity-card {
        grid-column: 1 / -1;
    }
    .field-position {
        width: 150px;
    }
    .bullpen-strip {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 900px) {
    .header-inner {
        grid-template-columns: 1fr;
        padding: 16px 0;
    }
    .header-brand-group,
    .main-nav,
    .auth-nav {
        justify-content: flex-start;
    }
    .hero-panel,
    .player-hero-detail {
        grid-template-columns: 1fr;
        flex-direction: column;
        align-items: flex-start;
    }
    .filter-grid {
        grid-template-columns: 1fr 1fr;
    }
    .score-summary-grid,
    .team-status-card .budget-row {
        grid-template-columns: 1fr 1fr;
    }
    .baseball-field {
        aspect-ratio: auto;
        display: grid;
        grid-template-columns: repeat(2, 1fr);
        gap: 12px;
        overflow: visible;
    }
    .field-bg {
        display: none;
    }
    .field-position,
    .pos-lf,.pos-cf,.pos-rf,.pos-ss,.pos-2b,.pos-3b,.pos-1b,.pos-p1,.pos-c,.pos-util {
        position: static;
        transform: none;
        width: auto;
    }
    .podium-wrap {
        flex-direction: column;
        align-items: stretch;
    }
    .podium-card,
    .podium-card.first {
        width: 100%;
        transform: none;
    }
}

@media (max-width: 640px) {
    .header-inner,
    .page-wrap {
        width: min(100% - 22px, 1480px);
    }
    .hero-panel,
    .content-card {
        border-radius: 18px;
        padding: 18px;
    }
    h1 {
        font-size: 34px;
    }
    .dashboard-grid,
    .metric-grid.four,
    .score-summary-grid,
    .stat-tile-grid,
    .filter-grid,
    .form-row-2,
    .baseball-field,
    .bullpen-strip {
        grid-template-columns: 1fr;
    }
    .hero-metric {
        width: 100%;
    }
}

/* ============================================================
   v3 color refresh: reference-inspired black / electric cyan
   ============================================================ */
:root {
    --bg: #030608;
    --panel: #080c10;
    --panel-2: #0b0f13;
    --panel-3: #10161c;
    --border: #232832;
    --border-soft: rgba(255, 255, 255, 0.105);
    --text: #f5f7f8;
    --muted: #7b8087;
    --primary: #08d4df;
    --primary-dark: #009aa6;
    --gold: #f1b948;
    --success: #27d17f;
    --warning: #f3b34d;
    --danger: #ff4d57;
    --pitcher: #ff5964;
    --shadow: 0 24px 80px rgba(0, 0, 0, 0.38);
    --radius: 18px;
}

html {
    background: var(--bg);
    scroll-behavior: smooth;
}

body {
    background:
        radial-gradient(circle at 50% 5%, rgba(8, 212, 223, 0.06), transparent 38%),
        radial-gradient(circle at 18% 24%, rgba(8, 212, 223, 0.035), transparent 32%),
        linear-gradient(180deg, #030608 0%, #05080b 45%, #030608 100%);
}

body::before {
    background-image: none;
    background: radial-gradient(circle at 50% 30%, rgba(8, 212, 223, 0.045), transparent 46%);
    mask-image: linear-gradient(to bottom, black, transparent 75%);
}

.site-header {
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    background: rgba(3, 6, 8, 0.82);
    backdrop-filter: blur(20px);
}

.header-inner {
    min-height: 66px;
}

.brand-mark {
    position: relative;
    width: 38px;
    height: 38px;
    border-radius: 14px;
    color: var(--primary);
    background: rgba(8, 212, 223, 0.08);
    border: 1px solid rgba(8, 212, 223, 0.20);
    box-shadow: none;
    font-weight: 950;
}

.brand-mark::after {
    content: "";
    position: absolute;
    width: 8px;
    height: 8px;
    right: -1px;
    bottom: -1px;
    border-radius: 999px;
    background: var(--primary);
    box-shadow: 0 0 18px rgba(8, 212, 223, 0.74);
}

.brand-text strong,
.text-primary {
    color: var(--primary);
}

.main-nav a,
.auth-nav a,
.tab-nav a {
    color: var(--muted);
    border: 1px solid transparent;
    background: transparent;
}

.main-nav a:hover,
.auth-nav a:hover,
.tab-nav a:hover {
    color: var(--text);
    background: rgba(255, 255, 255, 0.055);
}

.main-nav a.active,
.tab-nav a.active {
    color: var(--primary);
    background: rgba(8, 212, 223, 0.09);
    border-color: rgba(8, 212, 223, 0.16);
}

.auth-nav .nav-cta,
button,
.button-link,
.secondary-button {
    color: #041012;
    background: var(--primary);
    box-shadow: 0 0 28px rgba(8, 212, 223, 0.22);
}

.button-link.secondary,
.secondary-button,
.hero-secondary {
    color: var(--text);
    background: rgba(255, 255, 255, 0.025);
    border: 1px solid rgba(255, 255, 255, 0.08);
    box-shadow: none;
}

button:hover,
.button-link:hover,
.secondary-button:hover {
    box-shadow: 0 0 34px rgba(8, 212, 223, 0.32);
}

input,
select,
textarea {
    background: #05080b;
    border-color: rgba(255,255,255,0.10);
}

input:focus,
select:focus,
textarea:focus {
    border-color: rgba(8, 212, 223, 0.72);
    box-shadow: 0 0 0 3px rgba(8, 212, 223, 0.12);
}

.profile-menu {
    position: relative;
}

.profile-trigger {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 6px 8px 6px 6px;
    border: 0;
    border-radius: 999px;
    cursor: pointer;
    color: var(--text);
    background: transparent;
    box-shadow: none;
    user-select: none;
    transition: background 0.18s ease, transform 0.18s ease, box-shadow 0.18s ease;
}

.profile-trigger:hover,
.profile-menu.is-open .profile-trigger {
    background: rgba(255,255,255,0.055);
    transform: translateY(-1px);
    box-shadow: 0 0 24px rgba(8, 212, 223, 0.08);
}

.profile-avatar,
.profile-avatar-large {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 999px;
    color: var(--primary);
    background: radial-gradient(circle at 50% 30%, rgba(8, 212, 223, 0.18), rgba(8, 212, 223, 0.06));
    border: 1px solid rgba(8, 212, 223, 0.18);
}

.profile-avatar {
    width: 42px;
    height: 42px;
}

.profile-avatar svg,
.profile-avatar-large svg {
    width: 23px;
    height: 23px;
    fill: none;
    stroke: currentColor;
    stroke-width: 2.2;
    stroke-linecap: round;
    stroke-linejoin: round;
}

.profile-avatar-large {
    width: 92px;
    height: 92px;
    box-shadow: 0 0 48px rgba(8, 212, 223, 0.10);
}

.profile-avatar-large svg {
    width: 48px;
    height: 48px;
}

.profile-name {
    font-size: 16px;
    font-weight: 850;
    letter-spacing: -0.025em;
}

.profile-chevron {
    color: var(--muted);
    font-size: 24px;
    line-height: 1;
    transform: translateY(-2px);
    transition: transform 0.22s cubic-bezier(.2,.8,.2,1), color 0.18s ease;
}

.profile-menu.is-open .profile-chevron {
    color: var(--primary);
    transform: translateY(-2px) rotate(180deg);
}

.profile-dropdown {
    position: absolute;
    top: calc(100% + 12px);
    right: 0;
    width: 270px;
    padding: 10px 0;
    border-radius: 14px;
    background: rgba(5, 7, 10, 0.96);
    border: 1px solid rgba(255,255,255,0.13);
    box-shadow: 0 24px 80px rgba(0,0,0,0.52), 0 0 42px rgba(8, 212, 223, 0.06);
    z-index: 100;
    overflow: hidden;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transform: translateY(-10px) scale(0.97);
    transform-origin: top right;
    transition:
        opacity 0.22s ease,
        visibility 0.22s ease,
        transform 0.24s cubic-bezier(.2,.8,.2,1);
}

.profile-menu.is-open .profile-dropdown {
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
    transform: translateY(0) scale(1);
}

.profile-dropdown a {
    display: flex;
    align-items: center;
    gap: 18px;
    width: 100%;
    padding: 18px 22px;
    border-radius: 0;
    color: var(--text);
    background: transparent;
    box-shadow: none;
    font-size: 22px;
    font-weight: 650;
    text-decoration: none;
    transform: translateX(0);
    transition: background 0.16s ease, color 0.16s ease, transform 0.18s ease;
}

.profile-dropdown a:hover {
    color: var(--text);
    background: rgba(255,255,255,0.055);
    box-shadow: none;
    transform: translateX(4px);
}

.profile-dropdown .danger-link {
    color: #ff414b;
}

.profile-dropdown .danger-link:hover {
    color: #ff5f67;
}

.menu-icon {
    width: 34px;
    color: var(--muted);
    font-size: 30px;
    line-height: 1;
    text-align: center;
}

.danger-link .menu-icon {
    color: #ff414b;
}

.profile-separator {
    height: 1px;
    margin: 6px 0;
    background: rgba(255,255,255,0.10);
}

.page-wrap {
    padding-top: 30px;
}

.home-page-wrap {
    width: 100%;
    padding-top: 0;
}

.landing-hero {
    position: relative;
    min-height: calc(100svh - 73px);
    max-height: calc(100svh - 73px);
    border-bottom: 1px solid rgba(255,255,255,0.12);
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    margin-bottom: 0;
}

.landing-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background:
        radial-gradient(circle at 52% 45%, rgba(8, 212, 223, 0.075), transparent 28%),
        radial-gradient(circle at 35% 20%, rgba(8, 212, 223, 0.035), transparent 22%),
        linear-gradient(90deg, rgba(0,0,0,0.72), transparent 18%, transparent 78%, rgba(0,0,0,0.82));
}

.landing-glow {
    position: absolute;
    width: min(850px, 82vw);
    height: min(850px, 82vw);
    border-radius: 999px;
    background: rgba(8, 212, 223, 0.04);
    filter: blur(28px);
}

.landing-hero-inner {
    position: relative;
    z-index: 1;
    width: min(1000px, calc(100% - 36px));
    padding: 28px 0 42px;
}

.landing-hero h1 {
    margin: 0 0 30px;
    font-size: clamp(76px, 8.8vw, 136px);
    font-weight: 950;
    letter-spacing: -0.078em;
    line-height: 0.95;
}

.landing-hero h1 span {
    color: var(--primary);
    text-shadow: 0 0 36px rgba(8, 212, 223, 0.12);
}

.landing-copy {
    margin: 0 auto 64px;
    max-width: 850px;
    color: #777d82;
    font-size: clamp(22px, 2vw, 34px);
    font-weight: 600;
    line-height: 1.7;
    letter-spacing: -0.055em;
}

.landing-actions {
    display: flex;
    justify-content: center;
    gap: 24px;
    flex-wrap: wrap;
}

.hero-primary,
.hero-secondary {
    min-width: 180px;
    min-height: 64px;
    padding: 18px 28px;
    border-radius: 10px;
    font-size: 20px;
    font-weight: 900;
}

.hero-primary span {
    font-size: 32px;
    line-height: 0;
    transform: translateY(-1px);
}

.rankings-anchor {
    width: min(1480px, calc(100% - 36px));
    margin: 0 auto;
    padding-top: 58px;
    scroll-margin-top: 86px;
}

.landing-ranking-heading {
    margin-bottom: 22px;
}

.ranking-description {
    margin: 10px 0 0;
    max-width: 850px;
}

.hero-metric.slim {
    min-width: 150px;
    padding: 16px;
    background: rgba(255,255,255,0.025);
    border-color: rgba(255,255,255,0.10);
}

.hero-panel,
.content-card,
.auth-card {
    border-color: rgba(255,255,255,0.10);
    background: linear-gradient(180deg, rgba(11, 15, 19, 0.96), rgba(7, 10, 13, 0.96));
    box-shadow: var(--shadow);
}

.hero-panel::after {
    background: radial-gradient(circle, rgba(8, 212, 223, 0.12), transparent 70%);
}

.hero-metric,
.data-table th,
.table-wrap,
.bench-strip,
.filter-card,
.player-search-card,
.field-slot,
.stat-card,
.score-summary-item,
.profile-card-main {
    background-color: rgba(255,255,255,0.025);
    border-color: rgba(255,255,255,0.10);
}

.data-table th {
    background: #070a0d;
}

.data-table td {
    border-bottom-color: rgba(255,255,255,0.085);
}

.data-table tr:hover td {
    background: rgba(8, 212, 223, 0.045);
}

.team-badge,
.type-chip,
.position-badge,
.status-badge {
    border-color: rgba(255,255,255,0.12);
}

.points,
.price-up,
.budget-ok,
.count-ok {
    color: var(--primary);
}

.team-badge.team-default,
.uniform.team-default {
    --team-primary: #20262d;
    --team-secondary: var(--primary);
}

.profile-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.35fr);
    gap: 22px;
}

.profile-info-list {
    display: grid;
    gap: 12px;
    margin-top: 18px;
}

.profile-info-list div {
    display: flex;
    justify-content: space-between;
    gap: 14px;
    padding: 14px 0;
    border-bottom: 1px solid rgba(255,255,255,0.08);
}

.profile-info-list div:last-child {
    border-bottom: 0;
}

.profile-info-list span {
    color: var(--muted);
    font-weight: 800;
}

.profile-info-list strong {
    color: var(--text);
    text-align: right;
}

.mt-16 {
    margin-top: 16px;
}

@media (max-width: 860px) {
    .header-inner {
        grid-template-columns: 1fr;
        justify-items: stretch;
        padding: 12px 0;
    }

    .header-brand-group,
    .brand,
    .auth-nav,
    .main-nav {
        justify-content: center;
    }

    .header-brand-group {
        flex-wrap: wrap;
    }

    .profile-dropdown {
        left: 50%;
        right: auto;
        width: min(300px, calc(100vw - 36px));
        transform: translateX(-50%) translateY(-10px) scale(0.97);
        transform-origin: top center;
    }

    .profile-menu.is-open .profile-dropdown {
        transform: translateX(-50%) translateY(0) scale(1);
    }

    .landing-hero {
        min-height: calc(100svh - 142px);
        max-height: none;
    }

    .landing-hero h1 {
        font-size: clamp(56px, 17vw, 82px);
    }

    .landing-copy {
        font-size: 20px;
        margin-bottom: 44px;
    }

    .hero-primary,
    .hero-secondary {
