/* Fully custom select dropdowns: native option popups cannot be themed reliably on macOS/Chrome. */
.form-field {
    position: relative;
}

.select-native-hidden {
    position: absolute !important;
    width: 1px !important;
    height: 1px !important;
    opacity: 0 !important;
    pointer-events: none !important;
    left: 0 !important;
    bottom: 0 !important;
}

.custom-select {
    position: relative;
    width: 100%;
    z-index: 4;
}

.custom-select.is-open {
    z-index: 80;
}

.custom-select-trigger {
    width: 100%;
    min-height: 46px;
    padding: 0 42px 0 14px;
    border-radius: 14px;
    border: 1px solid rgba(255,255,255,0.14);
    background: #05080b;
    color: var(--text);
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.025);
    display: flex;
    align-items: center;
    justify-content: flex-start;
    text-align: left;
    font-size: 15px;
    font-weight: 850;
    letter-spacing: -0.02em;
}

.custom-select-trigger:hover,
.custom-select.is-open .custom-select-trigger {
    border-color: var(--primary);
    box-shadow: 0 0 0 3px rgba(0, 217, 255, 0.12), inset 0 1px 0 rgba(255,255,255,0.03);
    transform: none;
}

.custom-select-label {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.custom-select-arrow {
    position: absolute;
    right: 15px;
    top: 50%;
    width: 0;
    height: 0;
    border-left: 7px solid transparent;
    border-right: 7px solid transparent;
    border-top: 8px solid var(--primary);
    transform: translateY(-35%);
    transition: transform 0.16s ease;
}

.custom-select.is-open .custom-select-arrow {
    transform: translateY(-60%) rotate(180deg);
}

.custom-select-menu {
    position: absolute;
    left: 0;
    right: 0;
    top: calc(100% + 8px);
    max-height: 310px;
    overflow: auto;
    padding: 7px;
    border-radius: 16px;
    border: 1px solid rgba(0, 217, 255, 0.38);
    background: linear-gradient(180deg, #071118, #04080d);
    box-shadow: 0 22px 54px rgba(0,0,0,0.58), 0 0 0 1px rgba(255,255,255,0.035) inset;
    opacity: 0;
    visibility: hidden;
    transform: translateY(-8px) scale(0.985);
    transform-origin: top;
    transition: opacity 0.16s ease, transform 0.16s ease, visibility 0.16s ease;
}

.custom-select.is-open .custom-select-menu {
    opacity: 1;
    visibility: visible;
    transform: translateY(0) scale(1);
}

.custom-select-option {
    width: 100%;
    min-height: 38px;
    padding: 9px 11px;
    border-radius: 11px;
    background: transparent;
    color: rgba(255,255,255,0.86);
    box-shadow: none;
    display: flex;
    justify-content: flex-start;
    font-size: 14px;
    font-weight: 800;
    text-align: left;
}

.custom-select-option:hover,
.custom-select-option.is-selected {
    color: #06101f;
    background: linear-gradient(135deg, var(--primary), #62f0ff);
    transform: none;
    box-shadow: 0 10px 28px rgba(0, 217, 255, 0.16);
}

.custom-select-option.is-selected::before {
    content: '✓';
    margin-right: 8px;
    font-weight: 950;
}

.custom-select-menu::-webkit-scrollbar {
    width: 8px;
}

.custom-select-menu::-webkit-scrollbar-thumb {
    background: rgba(0, 217, 255, 0.28);
    border-radius: 999px;
}

