}

.ranking-page-shell::before,
.ranking-page-shell::after {
    content: "";
    position: fixed;
    pointer-events: none;
    z-index: -1;
    border-radius: 999px;
    filter: blur(10px);
    animation: rankingGlowFloat 12s ease-in-out infinite alternate;
}

.ranking-page-shell::before {
    width: 420px;
    height: 420px;
    left: -180px;
