/* =========================================================
   Account settings page
   ========================================================= */
.settings-page-shell {
    display: grid;
    gap: 18px;
    max-width: 1120px;
    margin: 0 auto 56px;
}

.settings-hero {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 18px;
    padding: 26px;
    overflow: hidden;
    position: relative;
}

.settings-hero::before {
    content: "";
    position: absolute;
    inset: -80px -120px auto auto;
    width: 320px;
    height: 320px;
    border-radius: 999px;
    background: radial-gradient(circle, rgba(8, 212, 223, 0.20), transparent 66%);
    pointer-events: none;
}

.settings-hero > * {
    position: relative;
    z-index: 1;
}

.settings-hero h1 {
    margin: 0 0 8px;
    font-size: clamp(30px, 4vw, 48px);
    letter-spacing: -0.05em;
}

.settings-hero p {
    margin: 0;
    max-width: 720px;
    color: var(--muted);
    line-height: 1.65;
}

.settings-summary-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 12px;
}

.settings-summary-card {
    padding: 18px 20px;
    border: 1px solid rgba(255,255,255,0.10);
    border-radius: 18px;
    background: rgba(5, 8, 11, 0.72);
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.035);
}

.settings-summary-card span {
    display: block;
    color: var(--muted);
    font-size: 12px;
    font-weight: 850;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 8px;
}

.settings-summary-card strong {
    display: block;
    color: var(--text);
    font-size: 20px;
    letter-spacing: -0.03em;
    word-break: break-word;
}

.settings-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 16px;
}

.settings-card {
    padding: 22px;
}

.settings-card-heading {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    gap: 14px;
    align-items: start;
    margin-bottom: 18px;
}

.settings-card-heading h2 {
    margin: 0 0 6px;
    font-size: 23px;
    letter-spacing: -0.04em;
}

.settings-card-heading p:not(.eyebrow) {
    margin: 0;
    color: var(--muted);
    line-height: 1.55;
}

.settings-card-icon {
    width: 42px;
    height: 42px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 14px;
    color: var(--primary);
    border: 1px solid rgba(8, 212, 223, 0.22);
    background: rgba(8, 212, 223, 0.08);
    font-size: 14px;
    font-weight: 950;
    letter-spacing: -0.04em;
}

.settings-card-icon.danger {
    color: #ff626b;
    border-color: rgba(255, 82, 82, 0.30);
    background: rgba(255, 82, 82, 0.10);
}

.settings-form {
    display: grid;
    gap: 14px;
}

.settings-two-col {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
}

.settings-form button {
    width: fit-content;
    min-width: 142px;
}

.settings-danger-card {
    border-color: rgba(255, 82, 82, 0.24) !important;
    background:
        radial-gradient(circle at 100% 0%, rgba(255, 82, 82, 0.10), transparent 38%),
        rgba(5, 8, 11, 0.78) !important;
}

