/* ==========================================================
   Support / Admin Support
   ========================================================== */
.support-shell {
    display: grid;
    gap: 22px;
    padding-bottom: 44px;
}

.support-hero-panel {
    position: relative;
    overflow: hidden;
}

.support-hero-panel::after {
    content: "";
    position: absolute;
    width: 220px;
    height: 220px;
    right: -58px;
    top: -72px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(0, 217, 255, 0.16), transparent 68%);
    pointer-events: none;
}

.support-layout,
.support-detail-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.45fr) minmax(320px, 0.55fr);
    gap: 22px;
    align-items: start;
}

.support-card,
.support-side-panel {
    min-width: 0;
}

.support-side-panel {
    display: grid;
    gap: 16px;
}

.support-form {
    display: grid;
    gap: 17px;
}

.support-form textarea {
    min-height: 180px;
    resize: vertical;
    line-height: 1.62;
}

.support-form .form-field small,
.optional-label {
    color: var(--muted);
    font-size: 12px;
    font-weight: 700;
}

.support-submit-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    flex-wrap: wrap;
    padding-top: 4px;
}

.support-submit-row p {
    margin: 0;
    color: var(--muted);
    font-size: 13px;
    line-height: 1.6;
}

.support-submit-row strong {
    color: var(--primary);
}

.support-guide-card {
    padding: 22px;
}

.support-guide-card h3 {
    margin: 4px 0 12px;
    font-size: 18px;
    letter-spacing: -0.03em;
}

.support-guide-card ul {
    margin: 0;
    padding-left: 18px;
    color: var(--muted);
    line-height: 1.72;
    font-size: 14px;
}

.support-guide-card.subtle {
    background: rgba(16, 35, 58, 0.72);
}

.support-status-guide {
    display: grid;
    gap: 8px;
}

.support-status-guide p {
    margin: -2px 0 8px;
    color: var(--muted);
    font-size: 13px;
    line-height: 1.55;
}

.support-summary-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 14px;
}

.support-summary-card {
    position: relative;
    overflow: hidden;
    border: 1px solid rgba(30, 58, 95, 0.72);
    border-radius: 18px;
    padding: 18px 18px 16px;
    background: linear-gradient(145deg, rgba(20, 41, 67, 0.92), rgba(10, 22, 40, 0.82));
    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.18);
}

.support-summary-card::after {
    content: "";
    position: absolute;
    inset: auto -30px -44px auto;
    width: 112px;
    height: 112px;
    border-radius: 50%;
    background: rgba(0, 217, 255, 0.08);
}

.support-summary-card span {
    display: block;
    color: var(--muted);
    font-size: 13px;
    font-weight: 800;
    margin-bottom: 8px;
}

.support-summary-card strong {
    display: block;
    color: var(--text);
    font-size: 28px;
    line-height: 1;
    letter-spacing: -0.03em;
}

.support-policy-note {
    border: 1px solid rgba(0, 217, 255, 0.16);
    border-radius: 14px;
    padding: 12px 14px;
    color: rgba(230, 248, 255, 0.76);
    background: rgba(0, 217, 255, 0.055);
    font-size: 13px;
    font-weight: 800;
    line-height: 1.55;
}

.compact-support-note {
    margin-bottom: 14px;
    padding: 10px 12px;
    font-size: 12px;
}

.support-ticket-list {
    display: grid;
    gap: 12px;
}

.support-ticket-row {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 14px;
    align-items: center;
    text-decoration: none;
    border: 1px solid rgba(30, 58, 95, 0.64);
    border-radius: 16px;
    padding: 16px 18px;
    background: rgba(10, 22, 40, 0.58);
    transition: transform 0.16s ease, border-color 0.16s ease, background 0.16s ease;
}

.support-ticket-row:hover {
    transform: translateY(-1px);
    border-color: rgba(0, 217, 255, 0.42);
    background: rgba(16, 35, 58, 0.84);
}

.support-ticket-main {
    display: grid;
    gap: 9px;
    min-width: 0;
}

.support-ticket-title-line {
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 0;
}

.support-ticket-title-line strong {
    min-width: 0;
    overflow: hidden;
    color: var(--text);
    font-size: 16px;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.support-ticket-meta {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    color: var(--muted);
    font-size: 12px;
    font-weight: 800;
}

.support-ticket-meta span {
    display: inline-flex;
    align-items: center;
    min-height: 24px;
    border-radius: 999px;
    padding: 4px 9px;
    background: rgba(255, 255, 255, 0.045);
    border: 1px solid rgba(255, 255, 255, 0.06);
}

.support-ticket-reply-preview {
    margin: 0;
    color: rgba(255, 255, 255, 0.78);
    font-size: 13px;
    line-height: 1.55;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.support-row-arrow {
    color: var(--primary);
    font-size: 28px;
    line-height: 1;
}

.support-status-badge,
.support-category-pill {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 999px;
    padding: 6px 10px;
    font-size: 12px;
    font-weight: 900;
    letter-spacing: -0.01em;
    white-space: nowrap;
}

.support-status-badge.open {
    color: #8ceeff;
    border: 1px solid rgba(0, 217, 255, 0.28);
    background: rgba(0, 217, 255, 0.10);
}

.support-status-badge.reviewing {
    color: #ffd08a;
    border: 1px solid rgba(255, 167, 38, 0.32);
    background: rgba(255, 167, 38, 0.12);
}

.support-status-badge.resolved {
    color: #97ffbd;
    border: 1px solid rgba(0, 230, 118, 0.28);
    background: rgba(0, 230, 118, 0.11);
}

.support-status-badge.closed {
    color: #b9c4d4;
    border: 1px solid rgba(139, 156, 179, 0.32);
    background: rgba(139, 156, 179, 0.12);
}

.support-category-pill {
    color: #dcefff;
    border: 1px solid rgba(255, 255, 255, 0.10);
    background: rgba(255, 255, 255, 0.06);
}

.support-detail-card,
.support-reply-card,
.support-admin-action-card {
    padding: 24px;
}

.support-detail-head {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
    margin-bottom: 18px;
}

.support-detail-meta {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
    margin: 0 0 20px;
}

.support-detail-meta div {
    border: 1px solid rgba(30, 58, 95, 0.58);
    border-radius: 14px;
    padding: 13px 14px;
    background: rgba(10, 22, 40, 0.48);
}

.support-detail-meta dt {
    color: var(--muted);
    font-size: 12px;
    font-weight: 900;
    margin-bottom: 6px;
}

.support-detail-meta dd {
    margin: 0;
    color: var(--text);
    font-weight: 800;
    word-break: break-word;
}

.support-message-box {
    border-radius: 16px;
    border: 1px solid rgba(0, 217, 255, 0.14);
    background: rgba(0, 217, 255, 0.055);
    padding: 18px;
}

.support-message-box h2,
.support-reply-card h2,
.support-admin-action-card h2 {
    margin: 0 0 12px;
    font-size: 18px;
    letter-spacing: -0.03em;
}

.support-danger-zone {
    display: grid;
    gap: 12px;
    margin-top: 18px;
    border: 1px solid rgba(255, 92, 122, 0.28);
    border-radius: 16px;
    padding: 16px;
    background: rgba(255, 92, 122, 0.075);
}

.support-danger-zone strong {
    display: block;
    color: #ffd3dc;
    font-size: 14px;
    font-weight: 900;
    margin-bottom: 6px;
}

.support-danger-zone p {
    margin: 0;
    color: rgba(255, 225, 231, 0.76);
    font-size: 12px;
    line-height: 1.55;
}

.danger-button {
    width: 100%;
    border-color: rgba(255, 92, 122, 0.35) !important;
    color: #fff !important;
    background: linear-gradient(135deg, rgba(255, 67, 101, 0.94), rgba(170, 21, 50, 0.94)) !important;
    box-shadow: 0 12px 30px rgba(255, 67, 101, 0.12) !important;
}

.danger-button:hover {
    transform: translateY(-1px);
    box-shadow: 0 16px 36px rgba(255, 67, 101, 0.18) !important;
}


.support-message-box p,
.support-reply-card p {
    margin: 0;
    color: rgba(255, 255, 255, 0.86);
    line-height: 1.75;
    white-space: pre-wrap;
    word-break: break-word;
}

.left-align-empty {
    align-items: flex-start;
    text-align: left;
}

.support-admin-filter {
    display: grid;
    grid-template-columns: 180px 220px minmax(240px, 1fr) auto;
    gap: 12px;
    align-items: end;
}

.support-admin-filter .form-field {
    margin: 0;
}

.support-filter-card {
    padding: 18px;
}

.admin-detail-grid {
    grid-template-columns: minmax(0, 1fr) minmax(360px, 0.55fr);
}

.admin-support-hero::after {
    background: radial-gradient(circle, rgba(255, 184, 0, 0.13), transparent 68%);
}

@media (max-width: 980px) {
    .support-layout,
    .support-detail-grid,
    .admin-detail-grid {
        grid-template-columns: 1fr;
    }

    .support-summary-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .support-admin-filter {
        grid-template-columns: 1fr 1fr;
    }

    .support-admin-filter button {
        width: 100%;
    }
}

@media (max-width: 640px) {
    .support-summary-grid,
    .support-admin-filter,
    .support-detail-meta {
        grid-template-columns: 1fr;
    }

    .support-ticket-row {
        padding: 14px;
    }

    .support-ticket-title-line {
        align-items: flex-start;
        flex-direction: column;
        gap: 7px;
    }

    .support-ticket-title-line strong,
    .support-ticket-reply-preview {
        white-space: normal;
    }

    .support-submit-row {
        align-items: stretch;
    }

    .support-submit-row button {
        width: 100%;
    }
}


/* Money/wealth header and income display polish */
.header-wealth-pill {
    display: inline-flex;
    align-items: center;
    gap: 9px;
    min-height: 42px;
    padding: 8px 12px;
    border-radius: 999px;
    color: var(--text) !important;
    text-decoration: none;
    background: rgba(255, 255, 255, 0.025);
    border: 1px solid rgba(8, 212, 223, 0.12);
    box-shadow: none;
    white-space: nowrap;
    transition: transform 0.18s ease, background 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
}

.header-wealth-pill:hover {
    transform: translateY(-1px);
    background: rgba(8, 212, 223, 0.075);
    border-color: rgba(8, 212, 223, 0.24);
    box-shadow: 0 0 24px rgba(8, 212, 223, 0.10);
}

.header-wealth-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: var(--primary);
}

.header-wealth-icon svg {
    width: 24px;
    height: 24px;
    fill: none;
    stroke: currentColor;
    stroke-width: 2;
    stroke-linecap: round;
    stroke-linejoin: round;
}

.header-wealth-pill strong {
    color: var(--text);
    font-size: 18px;
    font-weight: 850;
    letter-spacing: -0.025em;
}

.ranking-primary-number,
.ranking-neutral-number,
.podium-score-box strong,
.profile-v2-stat-card strong,
.my-team-metric-item strong,
.player-season-total-value,
.season-total-detail-value {
    font-variant-numeric: tabular-nums;
}

@media (max-width: 920px) {
    .header-wealth-pill {
        padding: 8px 10px;
    }

    .header-wealth-pill strong {
        font-size: 15px;
    }
}

@media (max-width: 640px) {
    .header-wealth-pill {
        order: -1;
        width: 100%;
        justify-content: center;
    }
}

/* ==========================================================
   Betting pages
   - MyPick 기존 글씨체/전역 숫자 스타일을 건드리지 않고 배팅 영역만 정리합니다.
   ========================================================== */
.betting-reveal {
    animation: rankingRevealUp 0.52s ease both;
    animation-delay: calc(var(--reveal-index, 0) * 70ms);
}

.betting-hero {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(240px, 320px);
    gap: 22px;
    align-items: stretch;
    padding: 28px;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 28px;
    background:
        radial-gradient(circle at 12% 10%, rgba(0, 229, 255, 0.13), transparent 34%),
        linear-gradient(145deg, rgba(8, 13, 18, 0.96), rgba(3, 8, 13, 0.94));
    box-shadow: 0 22px 60px rgba(0, 0, 0, 0.30);
    margin-bottom: 22px;
}

.betting-hero h1 {
    margin: 6px 0 10px;
    font-size: clamp(2rem, 4vw, 3.5rem);
    letter-spacing: -0.05em;
}

.betting-hero p {
    max-width: 760px;
    color: rgba(226, 232, 240, 0.72);
    line-height: 1.65;
    margin: 0;
}

.betting-wealth-panel {
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 8px;
    padding: 22px;
    border-radius: 24px;
    border: 1px solid rgba(34, 211, 238, 0.18);
    background: rgba(7, 12, 18, 0.72);
    min-width: 0;
}

.betting-wealth-panel span,
.betting-wealth-panel small {
    color: rgba(148, 163, 184, 0.88);
}

.betting-wealth-panel strong {
    display: block;
    font-size: clamp(1.55rem, 2.6vw, 2.25rem);
    line-height: 1.08;
    white-space: normal;
    overflow-wrap: anywhere;
}

.betting-wealth-panel a,
.betting-history-link {
    width: fit-content;
    color: rgba(103, 232, 249, 0.94);
    text-decoration: none;
    font-weight: 700;
}

.betting-shell {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(300px, 360px);
    gap: 22px;
    align-items: start;
}

.betting-board-main {
    min-width: 0;
}

.betting-date-tabs {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    margin-bottom: 18px;
}

.betting-date-tabs a {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 40px;
    padding: 0 16px;
    border-radius: 999px;
    border: 1px solid rgba(148, 163, 184, 0.16);
    background: rgba(15, 23, 42, 0.62);
    color: rgba(226, 232, 240, 0.86);
    text-decoration: none;
    font-weight: 800;
}

.betting-date-tabs a:hover {
    border-color: rgba(34, 211, 238, 0.35);
    color: #fff;
}

.betting-date-section {
    scroll-margin-top: 100px;
    margin-bottom: 26px;
}

.betting-date-heading {
    margin-bottom: 14px;
}

.betting-game-list {
    display: grid;
    gap: 16px;
}

.betting-game-card {
    position: relative;
    overflow: hidden;
    padding: 20px;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 26px;
    background:
        radial-gradient(circle at 15% 0%, rgba(34, 211, 238, 0.10), transparent 34%),
        linear-gradient(145deg, rgba(9, 14, 20, 0.95), rgba(4, 9, 14, 0.96));
    box-shadow: 0 18px 42px rgba(0, 0, 0, 0.28);
}

.betting-game-card.is-closed {
    opacity: 0.78;
}

.betting-game-topline {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 12px;
    margin-bottom: 18px;
}

.betting-time {
    color: #f8fafc;
    font-size: 0.98rem;
    font-weight: 900;
}

.betting-venue {
    margin-left: 8px;
    color: rgba(148, 163, 184, 0.9);
    font-weight: 700;
}

.betting-lock {
    display: inline-flex;
    align-items: center;
    min-height: 32px;
    padding: 0 12px;
    border-radius: 999px;
    font-size: 0.84rem;
    font-weight: 900;
    white-space: nowrap;
}

