.home-market-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 24px;
}

.home-popular-card {
    grid-column: span 2;
}

.home-mover-list,
.home-popular-list {
    display: grid;
    gap: 10px;
}

.home-mover-row,
.home-popular-row {
    display: grid;
    align-items: center;
    gap: 12px;
    min-height: 74px;
    padding: 12px 14px;
    border: 1px solid rgba(53, 236, 244, 0.11);
    border-radius: 18px;
    background: rgba(2, 8, 14, 0.38);
    transition: transform 180ms ease, border-color 180ms ease, background 180ms ease;
}

.home-mover-row {
    grid-template-columns: auto minmax(130px, 1fr) auto 132px;
}

.home-popular-row {
    grid-template-columns: 34px auto minmax(160px, 1fr) auto auto;
}

.home-mover-row:hover,
.home-popular-row:hover {
    transform: translateY(-2px);
    border-color: rgba(53, 236, 244, 0.28);
    background: rgba(9, 25, 33, 0.62);
}

.home-mover-name strong,
.home-popular-row strong {
    display: block;
    color: var(--text-main);
    font-size: 17px;
    letter-spacing: -0.04em;
}

.home-price-flow {
    text-align: right;
    display: grid;
    gap: 3px;
}

.home-price-flow small {
    color: var(--text-muted);
    font-weight: 800;
}

.home-price-flow em {
    font-size: 20px;
    font-style: normal;
    font-weight: 950;
}

.home-sparkline {
    width: 132px;
    height: 42px;
    overflow: visible;
}

.home-sparkline polyline {
    fill: none;
    stroke: var(--accent-cyan);
    stroke-width: 3.5;
    stroke-linecap: round;
    stroke-linejoin: round;
    filter: drop-shadow(0 0 7px rgba(53, 236, 244, 0.25));
}

.home-sparkline.down polyline {
    stroke: #fb7185;
    filter: drop-shadow(0 0 7px rgba(251, 113, 133, 0.18));
}

.home-popular-rank,
.home-standing-rank {
    color: var(--accent-cyan);
    font-size: 20px;
    font-weight: 950;
    letter-spacing: -0.04em;
}

.home-popular-row em {
    color: var(--text-main);
    font-style: normal;
    font-weight: 950;
}

.home-standings-list {
    display: grid;
    gap: 9px;
}

.home-standing-row {
    display: grid;
    grid-template-columns: 38px auto minmax(180px, 1fr) repeat(5, minmax(54px, auto));
    gap: 12px;
    align-items: center;
    padding: 12px 14px;
    border: 1px solid rgba(53, 236, 244, 0.10);
    border-radius: 18px;
    background: rgba(2, 8, 14, 0.35);
}

.home-standing-row.is-leader {
    border-color: rgba(53, 236, 244, 0.24);
    background: linear-gradient(90deg, rgba(53, 236, 244, 0.09), rgba(2, 8, 14, 0.36));
}

.home-standing-team b {
    display: block;
    color: var(--text-main);
    font-size: 16px;
}

.home-standing-team small {
    display: block;
    color: var(--text-muted);
    font-size: 12px;
    font-weight: 800;
}

.home-standing-row > span:not(.home-standing-team),
.home-standing-row > strong {
    color: var(--text-main);
    font-weight: 900;
}

.home-empty-panel {
    padding: 24px;
    color: var(--text-muted);
}

/* Profile honors */
.profile-honors-card {
    margin-top: 24px;
}

.profile-honors-count {
    color: var(--text-muted);
    font-weight: 900;
}

.profile-honor-showcase {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 14px;
}

.profile-honor-card {
    min-height: 148px;
    padding: 20px;
    border: 1px solid rgba(53, 236, 244, 0.15);
    border-radius: 22px;
    background: linear-gradient(145deg, rgba(9, 26, 34, 0.92), rgba(3, 11, 17, 0.96));
    display: flex;
    flex-direction: column;
    justify-content: space-between;
}

.profile-honor-card.honor-gold {
    border-color: rgba(250, 204, 21, 0.24);
    background: linear-gradient(145deg, rgba(49, 38, 10, 0.35), rgba(3, 11, 17, 0.96));
}

.profile-honor-card.honor-silver {
    border-color: rgba(203, 213, 225, 0.22);
}

.profile-honor-card.honor-bronze {
    border-color: rgba(251, 146, 60, 0.22);
}

.profile-honor-card span,
.profile-honor-timeline-row span {
    color: var(--text-muted);
    font-size: 13px;
    font-weight: 900;
}

.profile-honor-card strong {
    color: var(--text-main);
    font-size: 24px;
    line-height: 1.08;
    letter-spacing: -0.05em;
}

.profile-honor-card em,
.profile-honor-timeline-row em {
    color: var(--accent-cyan);
    font-style: normal;
    font-weight: 950;
}

.profile-honor-timeline {
    display: grid;
    gap: 8px;
    margin-top: 14px;
}

.profile-honor-timeline-row {
    display: grid;
    grid-template-columns: 130px minmax(0, 1fr) auto;
    gap: 12px;
    align-items: center;
    padding: 12px 14px;
    border: 1px solid rgba(53, 236, 244, 0.09);
    border-radius: 16px;
    background: rgba(2, 8, 14, 0.34);
}

.profile-honor-timeline-row strong {
    color: var(--text-main);
}

.profile-honor-empty {
    padding: 22px;
    border: 1px dashed rgba(148, 163, 184, 0.18);
    border-radius: 20px;
    color: var(--text-muted);
}

.profile-honor-empty strong {
    display: block;
    margin-bottom: 6px;
    color: var(--text-main);
    font-size: 19px;
}

@media (max-width: 1320px) {
    .home-feature-grid,
    .home-market-grid {
        grid-template-columns: 1fr;
    }

    .home-popular-card {
        grid-column: auto;
    }

    .home-best-team-card {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 980px) {
    .home-center-hero {
        min-height: 0;
        padding: 32px;
        align-items: flex-start;
        flex-direction: column;
        gap: 22px;
    }

    .home-center-summary-grid,
    .profile-honor-showcase {
        grid-template-columns: 1fr;
    }

    .home-mini-lineup {
        grid-template-columns: 1fr;
    }

    .home-mini-bullpen {
        grid-template-columns: repeat(5, minmax(0, 1fr));
        grid-template-rows: auto auto;
    }

    .home-mini-bullpen-title {
        grid-column: 1 / -1;
    }

    .home-mover-row {
        grid-template-columns: auto minmax(0, 1fr) auto;
    }

    .home-sparkline {
        grid-column: 1 / -1;
        width: 100%;
    }

    .home-standing-row {
        grid-template-columns: 32px auto minmax(130px, 1fr) repeat(2, auto);
    }

    .home-standing-row span:nth-last-child(-n+3) {
        display: none;
    }
}

@media (max-width: 680px) {
    .home-mini-field {
        min-height: 260px;
    }

    .home-mini-field .field-position {
        transform: translate(-50%, -50%) scale(0.58);
    }

    .home-popular-row {
        grid-template-columns: 28px auto minmax(0, 1fr);
    }

    .home-popular-row em,
    .home-popular-row > small {
        grid-column: 3;
    }

    .profile-honor-timeline-row {
        grid-template-columns: 1fr;
    }
}

